int main(){const int w=3,h=2,pad=6;const PF_Pixel16 p[6]={{32768,0,0,0},{32768,0,32768,32768},{32768,32768,0,32768},{32768,32768,32768,0},{32768,8192,8192,8192},{32768,24576,24576,24576}};size_t rb=w*sizeof(PF_Pixel16)+pad;std::vector<unsigned char>i(rb*h,0x3c),o(rb*h,0xa5);for(int y=0;y<h;y++)for(int x=0;x<w;x++)memcpy(i.data()+y*rb+x*sizeof(PF_Pixel16),p+y*w+x,sizeof(PF_Pixel16));PF_ParamDef ds[SM_NUM_PARAMS]{};PF_ParamDef*ps[SM_NUM_PARAMS]{};for(int n=0;n<SM_NUM_PARAMS;n++)ps[n]=ds+n;auto&in=ds[SM_INPUT].u.ld;in.data=i.data();in.width=w;in.height=h;in.rowbytes=rb;in.bitdepth=16;in.extent_hint={0,0,w,h};ds[SM_SMOOTHNESS].u.sd.value=100;ds[SM_SMOOTH_RANGE].u.sd.value=1;ds[SM_VERSION].u.pd.value=SMOOTHER_V2;ds[SM_GAMMA_MODE].u.pd.value=GAMMA_NONE;ds[SM_GAMMA_VALUE].u.fs_d.value=2.4;PF_LayerDef out{};out.data=o.data();out.width=w;out.height=h;out.rowbytes=rb;out.bitdepth=16;out.extent_hint={0,0,w,h};PF_InData id{};PF_OutData od{};int e=EffectMain(PF_Cmd_RENDER,&id,&od,ps,&out,nullptr);if(e)return e;printf("PF16 ");for(auto b:o)printf("%02x",b);puts("");return 0;}
